def perevod(n, base):
    t = ''
    while n > 0:
        t = str(n % base) + t
        n //= base
    return t

def to_base(n, b):
    r = ''
    while n: r = str(n % b) + r; n //= b
    return r

res = []
for N in range(1, 500):
    s = to_base(N, 6)
    if N % 3 == 0:
        s += s[-2:]
    else:
        val = (N % 3) * 5
        s += to_base(val, 6)
    R = int(s, 6)
    if R > 400:
        res.append(R)

print(min(res))
